{
  "name": "泰克 TDS5xx 系列数字示波器",
  "name_en": "Tektronix TDS5xx Series Digitizing Oscilloscope",
  "manufacturer": "Tektronix",
  "description": "用于泰克 TDS5xx 系列数字示波器的控制与读出，可进行通道与参考波形访问、数学波形选择、波形传输、触发设置、水平时基调整、自动测量以及屏幕截图获取，适合实验中的电信号观测与波形分析。",
  "description_en": "Control and readout for Tektronix TDS5xx series digitizing oscilloscopes, supporting channel and reference waveform access, math waveform selection, waveform transfer, trigger setup, horizontal timebase adjustment, automatic measurements, and screen capture for laboratory electrical signal observation and waveform analysis.",
  "tag_hints": [
    "oscilloscope",
    "waveform acquisition",
    "trigger control",
    "SCPI",
    "electrical signal measurement",
    "timebase control",
    "screen capture"
  ],
  "actions": [
    {
      "action_name": "auto-measurement",
      "description": "获取指定的示波器测量对象。",
      "description_en": "Get a specified oscilloscope measurement object."
    },
    {
      "action_name": "auto-channel",
      "description": "获取指定的示波器通道对象。",
      "description_en": "Get a specified oscilloscope channel object."
    },
    {
      "action_name": "auto-ref",
      "description": "获取指定的参考波形通道对象。",
      "description_en": "Get a specified reference waveform channel object."
    },
    {
      "action_name": "auto-math",
      "description": "获取数学运算波形数据源对象。",
      "description_en": "Get the MATH waveform data source object."
    },
    {
      "action_name": "auto-sources",
      "description": "获取所有活动数据源列表。",
      "description_en": "Get the list of all active sources."
    },
    {
      "action_name": "auto-data_source",
      "description": "获取/设置波形传输的数据源。",
      "description_en": "Get/set the data source for waveform transfer."
    },
    {
      "action_name": "auto-data_width",
      "description": "获取/设置波形传输的数据宽度。",
      "description_en": "Get/set the data width for waveform transfers."
    },
    {
      "action_name": "auto-force_trigger",
      "description": "强制触发示波器采集。",
      "description_en": "Force-trigger the oscilloscope acquisition."
    },
    {
      "action_name": "auto-horizontal_scale",
      "description": "获取/设置水平时基刻度。",
      "description_en": "Get/set the horizontal scale."
    },
    {
      "action_name": "auto-trigger_level",
      "description": "获取/设置触发电平。",
      "description_en": "Get/set the trigger level."
    },
    {
      "action_name": "auto-trigger_coupling",
      "description": "获取/设置触发耦合方式。",
      "description_en": "Get/set the trigger coupling."
    },
    {
      "action_name": "auto-trigger_slope",
      "description": "获取/设置触发斜率。",
      "description_en": "Get/set the trigger slope."
    },
    {
      "action_name": "auto-trigger_source",
      "description": "获取/设置触发源。",
      "description_en": "Get/set the trigger source."
    },
    {
      "action_name": "auto-clock",
      "description": "获取/设置示波器时钟。",
      "description_en": "Get/set the oscilloscope clock."
    },
    {
      "action_name": "auto-display_clock",
      "description": "获取/设置屏幕时钟显示状态。",
      "description_en": "Get/set the visibility of the on-screen clock."
    },
    {
      "action_name": "auto-get_hardcopy",
      "description": "获取示波器显示屏截图。",
      "description_en": "Get a screenshot of the oscilloscope display."
    },
    {
      "action_name": "auto-read",
      "description": "读取当前数据源的数据。",
      "description_en": "Read data from the current data source."
    },
    {
      "action_name": "auto-name",
      "description": "获取仪器名称。",
      "description_en": "Get the instrument name."
    },
    {
      "action_name": "auto-read_waveform",
      "description": "读取波形数据。",
      "description_en": "Read waveform data."
    },
    {
      "action_name": "auto-coupling",
      "description": "获取/设置通道耦合方式。",
      "description_en": "Get/set the channel coupling."
    },
    {
      "action_name": "auto-bandwidth",
      "description": "获取/设置通道带宽限制。",
      "description_en": "Get/set the channel bandwidth limit."
    },
    {
      "action_name": "auto-impedance",
      "description": "获取/设置通道输入阻抗。",
      "description_en": "Get/set the channel input impedance."
    },
    {
      "action_name": "auto-probe",
      "description": "获取/设置探头倍率。",
      "description_en": "Get/set the probe attenuation factor."
    },
    {
      "action_name": "auto-scale",
      "description": "获取/设置通道垂直刻度。",
      "description_en": "Get/set the channel vertical scale."
    }
  ]
}

